// cga.js -- composite page driver.
//
// Each cga* server serves its own HTML *fragment* on its own port. This script
// fetches each fragment (per the data-comp / data-route attributes in the
// slots) and drops it into the layout grid. Clicking an overview box refreshes
// every fragment, then loads that component's /detail into the bottom detail
// area. All content is read-only.

// CGA_CONFIG maps component -> base URL. cga-config.js (generated by cga-run)
// may override this; otherwise fall back to the default localhost ports.
const DEFAULTS = {
  cgasv: "http://127.0.0.1:8601",
  cgadl: "http://127.0.0.1:8602",
  cgaql: "http://127.0.0.1:8603",
  cgamr: "http://127.0.0.1:8604",
  cgamu: "http://127.0.0.1:8605",
  cgasi: "http://127.0.0.1:8606",
  cgamx: "http://127.0.0.1:8607",
  cgaex: "http://127.0.0.1:8608",
};
const CONFIG = Object.assign({}, DEFAULTS, window.CGA_CONFIG || {});
const THEME_STORAGE_KEY = "cga.theme";

function setTheme(theme, persist = true) {
  const value = theme === "light" ? "light" : "dark";
  document.documentElement.dataset.theme = value;
  const button = document.getElementById("cga-theme-toggle");
  const next = value === "dark" ? "light" : "dark";
  button.textContent = `${next} theme`;
  button.setAttribute("aria-label", `switch to ${next} theme`);
  button.title = `switch to ${next} theme`;
  if (persist) {
    try {
      localStorage.setItem(THEME_STORAGE_KEY, value);
    } catch (_error) {
      // The visual choice still applies when storage is disabled.
    }
  }
}

function initializeTheme() {
  let stored = "dark";
  try {
    stored = localStorage.getItem(THEME_STORAGE_KEY) || "dark";
  } catch (_error) {
    // Storage can be disabled; the explicit dark default remains usable.
  }
  setTheme(stored, false);
  document.getElementById("cga-theme-toggle").addEventListener("click", () => {
    setTheme(
      document.documentElement.dataset.theme === "dark" ? "light" : "dark",
    );
  });
}

function baseFor(comp) {
  return CONFIG[comp] || DEFAULTS[comp];
}

async function fetchFragment(comp, route) {
  const url = baseFor(comp) + route;
  const resp = await fetch(url, { cache: "no-store" });
  if (!resp.ok) throw new Error(`${comp}${route}: HTTP ${resp.status}`);
  return await resp.text();
}

async function loadSlot(el) {
  const comp = el.dataset.comp;
  const route = el.dataset.route;
  try {
    el.innerHTML = await fetchFragment(comp, route);
  } catch (e) {
    el.innerHTML =
      `<div class="cga-err">${comp} unavailable: ${String(e.message || e)}` +
      `<br/><small>${baseFor(comp)}${route}</small></div>`;
  }
}

async function showDetail(comp) {
  document.getElementById("cga-detail-which").textContent = comp;
  const el = document.getElementById("cga-detail");
  el.dataset.comp = comp;
  el.dataset.route = "/detail";
  await loadSlot(el);
}

let selectedDetail = "cgamu";
let refreshPromise = null;
let refreshAgain = false;

async function refreshAll() {
  // Coalesce timer/reload/click requests. A request received during a refresh
  // schedules another complete pass, so a click can never be lost behind the
  // periodic update that happened to be in flight.
  if (refreshPromise) {
    refreshAgain = true;
    return refreshPromise;
  }
  refreshPromise = (async () => {
    do {
      refreshAgain = false;
      await refreshOverview();
      await showDetail(selectedDetail);
    } while (refreshAgain);
  })();
  try {
    await refreshPromise;
  } finally {
    refreshPromise = null;
  }
}

// Refresh only the overview slots (never the detail). The periodic timer uses
// this so that in-progress typed input in an editable detail view (e.g. the
// cgasi Findings filters) is never wiped out from under the user. The detail is
// refreshed only on an explicit reload, an overview click, or after an apply.
async function refreshOverview() {
  const slots = Array.from(
    document.querySelectorAll(".cga-slot[data-comp]"),
  ).filter((el) => el.id !== "cga-detail");
  await Promise.all(slots.map(loadSlot));
}

// Send one cga* command to the cgamx cmd server, exactly as if a user or LLM
// had typed it in the shell. `argv` is the command as an argument vector (no
// quoting ambiguity). Returns the parsed JSON result.
async function runCommand(argv) {
  const url = baseFor("cgamx") + "/run";
  const resp = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ argv }),
    cache: "no-store",
  });
  return await resp.json();
}

// Read the editable cgasi Findings view and turn it into a `cgasi view` argv.
function cgasiViewArgv(detailEl) {
  const argv = ["cgasi", "view"];
  const sel = detailEl.querySelector('[data-view-field="erc"]');
  if (sel && sel.value) argv.push("--erc", sel.value);
  // Always clear first, then re-add the non-empty filters, so emptying a field
  // removes that filter (matching `cgasi view` semantics).
  argv.push("--clear");
  detailEl.querySelectorAll("[data-view-filter]").forEach((inp) => {
    const label = inp.dataset.viewFilter;
    const value = inp.value.trim();
    if (value) argv.push("--" + label, value);
  });
  return argv;
}

async function applyDetail(detailEl) {
  const comp = detailEl.dataset.comp;
  if (comp !== "cgasi") return;
  const argv = cgasiViewArgv(detailEl);
  try {
    const result = await runCommand(argv);
    if (!result.ok) {
      window.alert(
        "apply failed (exit " +
          result.exit_code +
          "):\n" +
          (result.output || ""),
      );
    }
  } catch (e) {
    window.alert("apply failed: " + String(e.message || e));
  }
  await refreshAll();
}

function wire() {
  // Click any overview box -> refresh every overview, then show its detail.
  document.querySelectorAll(".cga-flow").forEach((flow) => {
    flow.addEventListener("click", async (ev) => {
      const box = ev.target.closest(".cga-box[data-comp]");
      if (box) {
        selectedDetail = box.dataset.comp;
        await refreshAll();
      }
    });
  });
  document.getElementById("cga-reload").addEventListener("click", refreshAll);
  // Apply button inside a detail fragment: send the assembled cga* command to
  // the cgamx cmd server, then refresh so the view reflects the new session.
  document
    .getElementById("cga-detail")
    .addEventListener("click", async (ev) => {
      const btn = ev.target.closest(".cga-apply");
      if (btn) await applyDetail(document.getElementById("cga-detail"));
    });
}

initializeTheme();
wire();
refreshAll();
// No periodic auto-refresh: it would replace live fragments (including the
// editable cgasi Findings view) out from under the user and wipe unapplied
// input. The page is a snapshot -- use the reload button (or click an overview
// box, or apply a change) to refresh from the current session CGAST.
